import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implementation of Dijkstra's algorithm to find the shortest path in a weighted directed graph."""

    priority_queue = []
    heapq.heappush(priority_queue, (0, start))
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == end:
            break

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    path = []
    current_node = end

    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]

    path.reverse()

    if distances[end] == float('inf'):
        return (float('inf'), [])

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implementation of the Bellman-Ford algorithm to find the shortest path in a weighted directed graph."""

    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessors = {node: None for node in graph}

    nodes = list(graph.keys())

    for _ in range(len(nodes) - 1):
        for node in nodes:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    for node in nodes:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])  # Negative weight cycle detected

    path = []
    current_node = end

    while current_node is not None:
        path.append(current_node)
        current_node = predecessors[current_node]

    path.reverse()

    if distances[end] == float('inf'):
        return (float('inf'), [])

    return (distances[end], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implementation of the Floyd-Warshall algorithm to find the shortest path in a weighted directed graph."""

    # Initialize distance and next_node matrices
    distances = {node: {other: float('inf') for other in graph} for node in graph}
    next_node = {node: {other: None for other in graph} for node in graph}

    for node in graph:
        distances[node][node] = 0

    for node, edges in graph.items():
        for neighbor, weight in edges:
            distances[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    # Floyd-Warshall algorithm
    for k in graph:
        for i in graph:
            for j in graph:
                if distances[i][j] > distances[i][k] + distances[k][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]
                    next_node[i][j] = next_node[i][k]

    # Reconstruct the path
    path = []
    current = start

    if distances[start][end] == float('inf'):
        return (float('inf'), [])

    while current is not None:
        path.append(current)
        if current == end:
            break
        current = next_node[current][end]

    return (distances[start][end], path)

